#![allow(clippy::unwrap_used)]
use ulw_loop_core::checkpoint::{checkpoint_ulw_loop, CheckpointUlwLoopArgs};
use ulw_loop_core::domain_types::*;
use ulw_loop_core::plan_io::write_plan;

fn goal(id:&str,status:&str,criteria:Vec<UlwLoopSuccessCriterion>)->UlwLoopItem{UlwLoopItem{id:id.into(),title:id.into(),objective:"Objective".into(),status:status.into(),success_criteria:criteria,attempt:1,created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),started_at:None,completed_at:None,failed_at:None,review_blocked_at:None,evidence:None,failure_reason:None,steering_status:None,superseded_by:None,supersedes:None,blocked_reason:None,blocker_signature:None,blocker_occurrence_count:None,required_external_decision:None,non_retriable:None,steering_evidence:None,steering_rationale:None}}
fn c(status:&str)->UlwLoopSuccessCriterion{UlwLoopSuccessCriterion{id:"C001".into(),scenario:"s".into(),user_model:"happy".into(),expected_evidence:"e".into(),status:status.into(),essential:Some(true),captured_evidence:None,captured_at:None,notes:None,artifacts:None}}
fn plan(gs:Vec<UlwLoopItem>)->UlwLoopPlan{UlwLoopPlan{version:1,revision:Some(1),codex_goal_mode:Some("aggregate".into()),brief:Some("brief".into()),ledger_reset_revision:None,evidence_layout_version:Some(2),goals_path:".omo/ulw-loop/goals.json".into(),ledger_path:".omo/ulw-loop/ledger.jsonl".into(),brief_path:".omo/ulw-loop/brief.md".into(),created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),active_goal_id:Some(gs.last().unwrap().id.clone()),goals:gs,codex_objective:Some("aggregate objective".into()),codex_objective_aliases:None,acknowledged_driver_objectives:None,aggregate_completion:None,validation_batches:None}}
fn attempt(p:UlwLoopPlan,id:&str,snapshot:Option<serde_json::Value>,gate:Option<serde_json::Value>)->Result<ulw_loop_core::checkpoint::CheckpointUlwLoopResult,ulw_loop_core::UlwLoopError>{let t=tempfile::tempdir().unwrap();std::fs::create_dir_all(t.path().join(".omo/ulw-loop")).unwrap();write_plan(t.path(),p,None).unwrap();checkpoint_ulw_loop(t.path(),&CheckpointUlwLoopArgs{goal_id:id.into(),status:"complete".into(),evidence:"final work complete and validation passed".into(),codex_goal_json:snapshot.map(|v|v.to_string()),quality_gate_json:gate.map(|v|v.to_string())},None,None)}
fn snap(status:&str)->serde_json::Value{serde_json::json!({"goal":{"objective":"aggregate objective","status":status}})}

#[test]fn omo_senpi_gate_without_code_review_is_rejected_without_gate_support(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),None).is_err());}
#[test]fn lazycodex_gate_without_code_review_requires_gate(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),None).is_err());}
#[test]fn gate_with_code_review_is_not_accepted_as_empty_gate(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);let gate=serde_json::json!({"codeReview":{}});assert!(attempt(p,"G002",Some(snap("complete")),Some(gate)).is_err());}
#[test]fn malformed_gate_reports_error(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),Some(serde_json::json!({"manualQa":{}}))).is_err());}
#[test]fn mismatched_objective_and_gate_defects_are_rejected(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);let r=attempt(p,"G002",Some(serde_json::json!({"goal":{"objective":"wrong","status":"complete"}})),Some(serde_json::json!({"gateReview":{"recommendation":"REJECT"}})));assert!(r.is_err());}
#[test]fn final_goal_requires_quality_gate_json(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),None).is_err());}
#[test]fn valid_criteria_without_gate_is_rejected(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),Some(serde_json::json!({}))).is_err());}
#[test]fn earlier_nonessential_pending_criteria_still_blocks_final(){let mut earlier=goal("G001","complete",vec![c("pass")]);earlier.success_criteria.push(UlwLoopSuccessCriterion{id:"C002".into(),scenario:"s".into(),user_model:"happy".into(),expected_evidence:"e".into(),status:"pending".into(),essential:Some(false),captured_evidence:None,captured_at:None,notes:None,artifacts:None});let p=plan(vec![earlier,goal("G002","in_progress",vec![c("pass")])]);assert!(attempt(p,"G002",Some(snap("complete")),Some(serde_json::json!({}))).is_err());}
#[test]fn missing_artifact_gate_is_rejected(){let p=plan(vec![goal("G001","complete",vec![c("pass")]),goal("G002","in_progress",vec![c("pass")])]);let gate=serde_json::json!({"manualQa":{"artifactRefs":[{"id":"x","kind":"cli-transcript","description":"x","path":"missing.txt"}]}});assert!(attempt(p,"G002",Some(snap("complete")),Some(gate)).is_err());}
#[test]fn per_story_mode_requires_all_criteria(){let mut p=plan(vec![goal("G001","in_progress",vec![c("pass"),UlwLoopSuccessCriterion{id:"C002".into(),scenario:"s".into(),user_model:"happy".into(),expected_evidence:"e".into(),status:"pending".into(),essential:Some(false),captured_evidence:None,captured_at:None,notes:None,artifacts:None}])]);p.codex_goal_mode=Some("per_story".into());assert!(attempt(p,"G001",Some(snap("complete")),None).is_err());}


